-- 34: PRE-FLIGHT for the website migration 20261117100000_agreement_access. Read-only.
-- One result set. Rows 1 to 4 must say ok = true (what the migration builds on is there, and none of its names is taken). Any later row is information only (it never blocks).
select * from (
  select 1 as n, 'the functions this builds on exist' as check_name,
         (to_regprocedure('public.agreement_side(public.site_agreements, text)') is not null and to_regprocedure('public.night_booking_ids(uuid, date)') is not null and to_regprocedure('public.venue_timezone(uuid)') is not null and to_regprocedure('public.venue_setup_log(text, text, uuid, uuid, jsonb)') is not null and to_regprocedure('public.can_access_event(uuid, text[])') is not null and to_regprocedure('public.is_org_member(uuid, text[])') is not null) as ok,
         concat_ws(', ', case when to_regprocedure('public.agreement_side(public.site_agreements, text)') is null then 'public.agreement_side missing' end, case when to_regprocedure('public.night_booking_ids(uuid, date)') is null then 'public.night_booking_ids missing' end, case when to_regprocedure('public.venue_timezone(uuid)') is null then 'public.venue_timezone missing' end, case when to_regprocedure('public.venue_setup_log(text, text, uuid, uuid, jsonb)') is null then 'public.venue_setup_log missing' end, case when to_regprocedure('public.can_access_event(uuid, text[])') is null then 'public.can_access_event missing' end, case when to_regprocedure('public.is_org_member(uuid, text[])') is null then 'public.is_org_member missing' end) as detail
  union all
  select 2, 'the tables and columns this builds on exist',
         (to_regclass('public.site_agreement_versions') is not null and to_regclass('public.site_agreements') is not null and to_regclass('public.site_events') is not null and to_regclass('public.site_orders') is not null and to_regclass('public.site_table_bookings') is not null and to_regclass('public.site_ticket_tiers') is not null and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_agreements' and column_name = 'status') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_agreements' and column_name = 'active_version') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_agreement_versions' and column_name = 'terms') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_orders' and column_name = 'checked_in_at') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_orders' and column_name = 'amount_total_cents') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_ticket_tiers' and column_name = 'event_id') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_events' and column_name = 'org_id') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_events' and column_name = 'start_date') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_table_bookings' and column_name = 'guest_count')),
         'site_agreement_versions.terms, site_agreements.active_version, site_agreements.status, site_events.org_id, site_events.start_date, site_orders.amount_total_cents, site_orders.checked_in_at, site_table_bookings.guest_count, site_ticket_tiers.event_id'
  union all
  select 3, 'none of the new names is taken (7 functions, 1 tables, 0 columns, 0 triggers)',
         (not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['agreement_grant_keys', 'agreement_grant_available', 'agreement_in_force', 'set_agreement_grant', 'agreement_grants', 'organizer_venue_access', 'organizer_event_sales'])) and to_regclass('public.site_agreement_grants') is null),
         concat_ws(', ', coalesce((select string_agg(p.proname, ', ') from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['agreement_grant_keys', 'agreement_grant_available', 'agreement_in_force', 'set_agreement_grant', 'agreement_grants', 'organizer_venue_access', 'organizer_event_sales'])), ''), case when to_regclass('public.site_agreement_grants') is not null then 'table site_agreement_grants exists' else '' end)
  union all
  select 4, 'the roles exist (the functions are granted to authenticated and service_role and taken from anon)',
         exists (select 1 from pg_roles where rolname = 'service_role') and exists (select 1 from pg_roles where rolname = 'authenticated') and exists (select 1 from pg_roles where rolname = 'anon'),
         'service_role, authenticated, anon'
  union all
  select 5, 'INFORMATION: open agreements (these are what the club will be able to share things under once they are active)', true, (select count(*)::text from public.site_agreements where status in ('active', 'changes_pending')) || ' active, ' || (select count(*)::text from public.site_agreements where status not in ('active', 'changes_pending', 'declined', 'cancelled')) || ' being agreed'
) r order by n;
